insert into committees (id, name, purpose, head_title, note) values ('c_social', 'اللجنة الاجتماعية', 'تحقيق التكافل الاجتماعي: حصر المحتاجين من أبناء العائلة، سد احتياجاتهم الأساسية، والصرف عليهم.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_communication', 'لجنة التواصل', 'تعزيز الروابط بين أفراد العائلة: تنظيم اللقاءات الدورية، تحديث قاعدة بيانات الأفراد، وإدارة شبكات التواصل الداخلية.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_finance_endowments', 'لجنة تنمية الموارد المالية والأوقاف', 'تنمية الموارد المالية للصندوق: إيجاد موارد مالية، تأسيس أوقاف، وتحقيق الاستدامة المالية.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_development', 'لجنة التطوير والتأهيل', 'تطوير وتأهيل أفراد العائلة: البناء العقلي والمهني، تجاوز تحديات سوق العمل، وتنمية المهارات.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_marriage_loan_review', 'برنامج إقراض الزواج / الفحص والتحصيل', 'دعم أفراد العائلة الراغبين في الزواج: دراسة الأوضاع، التوصية بالقروض الحسنة، ومتابعة التحصيل.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_marriage_loan_credit', 'برنامج إقراض الزواج / الائتمان', 'اعتماد صرف القروض لراغبي الزواج: دراسة الطلبات، اعتماد الصرف، وإعداد التقارير المالية الدورية.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_heritage', 'تراث العائلة العلمي', 'توثيق تراث العائلة العلمي بجميع أشكاله: المقروء، المطبوع، المخطوط، المرئي، والمسموع، وحفظه بطرق حديثة.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_excellence', 'جائزة التميز', 'تحفيز أبناء العائلة وتكريم المتميزين: الإشراف على الجائزة، وضع معايير التميز، وترشيح المتميزين.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_governance', 'المراجعة والحوكمة', 'رفع مستوى حوكمة الصندوق: مراجعة الأنظمة واللوائح، ومتابعة تطبيق اللجان لها.', '', '');
insert into committees (id, name, purpose, head_title, note) values ('c_executive', 'اللجنة التنفيذية', 'متابعة أعمال لجان الصندوق واقتراح الخطط التصحيحية، وجمع تقارير اللجان وإعداد العروض لمجلس الأمناء.', 'المدير التنفيذي للصندوق', 'أعضاء اللجنة هم مقررو بقية اللجان بحكم مناصبهم تلقائيًا.');
